import{_ as t,o,c as r,ak as a}from"./chunks/framework.Cq0X4QeM.js";const h=JSON.parse('{"title":"Initial access (protocols)","description":"","frontmatter":{"authors":"ShutdownRepo, blepdoge","category":"infra"},"headers":[],"relativePath":"infra/protocols/index.md","filePath":"infra/protocols/index.md"}'),n={name:"infra/protocols/index.md"};function s(i,e,c,d,l,m){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="initial-access-protocols" tabindex="-1">Initial access (protocols) <a class="header-anchor" href="#initial-access-protocols" aria-label="Permalink to &quot;Initial access (protocols)&quot;">​</a></h1><h2 id="theory" tabindex="-1">Theory <a class="header-anchor" href="#theory" aria-label="Permalink to &quot;Theory&quot;">​</a></h2><p>To gain initial access into an information system, one of the most common vectors will be exploiting badly configured protocols inside the enterprise network. If companies don&#39;t necessarily implement each of the protocols listed in this category, most of them can have configuration vulnerabilities that will allow you to gain an entry point into the system. Some insecure protocols, like Telnet, HTTP, or old versions of SMB, are more rarely found in enteprise systems or services (but always check, you never know if some legacy machines have them activated 😉). Knowing which tools exist to manipulate these protocols and their possible misconfigurations is essential ! You may find it interesting to explore the following :</p><ul><li>Broken authentication (FTP anonymous login, SSH default creds, open SMB shares) ;</li><li>Information disclosure (DBMS protocols such as MySQL or MSSQL, or usage of HTTP instead of HTTPS) ;</li><li>Exploiting enterprise authentication methods such as <a href="https://www.hackthebox.com/blog/8-powerful-kerberos-attacks" target="_blank" rel="noreferrer">Kerberos</a> tickets or LDAP requests, in order to compromise either a user or a service ;</li><li>Data exfiltration using standard file exchange protocols, but also more unconventional methods such as <a href="https://repository.root-me.org/R%C3%A9seau/EN%20-%20Data%20exfiltration%20and%20DNS%20-%20Infoblox.pdf" target="_blank" rel="noreferrer">DNS data exfiltration</a></li><li>Or even gaining direct access/code execution to a machine using one of the protocols below, and tools like <code>impacket</code> or <code>NetExec</code>, which could then open many doors !</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="https://www.netexec.wiki/" target="_blank" rel="noreferrer">NetExec</a> is a great network service exploitation tool that can help in exploiting protocols and assessing the security posture of an information system. It supports a lot of common enterprise protocols : smb, ssh, ldap, wmi, rdp, mssql... in combination with different auth methods (Kerberos, standard credentials).</p></div><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><h3 id="well-known-ports" tabindex="-1">Well known ports <a class="header-anchor" href="#well-known-ports" aria-label="Permalink to &quot;Well known ports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Common port</th><th>Protocol</th><th>Description</th></tr></thead><tbody><tr><td><code>21/TCP</code></td><td>FTP</td><td><strong>File Transfer Protocol</strong> - Standard network protocol used for transferring files from one host to another over a TCP-based network. FTP uses a client-server architecture and operates in both active and passive modes. It lacks encryption, making it less secure for transmitting sensitive data.</td></tr><tr><td><code>22/TCP</code></td><td>SSH</td><td><strong>Secure Shell</strong> - Cryptographic network protocol to operate services and devices securely over an unsecured network. SSH uses public-key cryptography for authentication and symmetric encryption (e.g., AES, 3DES) for data confidentiality and integrity. It is widely used for remote login, command execution, and secure file transfers.</td></tr><tr><td><code>23/TCP</code></td><td>Telnet</td><td>Provides a command-line interface for communication with a remote device. Telnet transmits data, including passwords, in plaintext, making it vulnerable to eavesdropping and man-in-the-middle attacks. It has largely been replaced by SSH for secure remote access.</td></tr><tr><td><code>53/UDP</code> or <code>53/TCP</code></td><td>DNS</td><td><strong>Domain Name System</strong> - Hierarchical and decentralized naming system for computers, services, or other resources connected to the Internet or a private network. DNS translates human-readable domain names into IP addresses using a distributed database system. It can operate over both UDP and TCP, with UDP being more common for queries and TCP for zone transfers.</td></tr><tr><td><code>80/TCP</code></td><td>HTTP</td><td><strong>HyperText Transfer Protocol</strong> - Application layer protocol that defines communication between a client and server over TCP, using a request-response model. Key features include request methods like GET, POST, PUT, and DELETE; response status codes (e.g., 200 OK, 404 Not Found); headers for metadata; and MIME types for data formats. It is not secure by default, HTTPS being preferred for secure communications.</td></tr><tr><td><code>88/TCP</code></td><td>Kerberos</td><td>The default authentication protocol for Active Directory, thus often used in enterprise environments. It is designed to provide strong authentication for client/server applications using secret-key cryptography. Kerberos uses symmetric encryption (e.g., DES, AES) and a combination of Authentication Servers and Ticket-Granting Servers (TGS) to authenticate users and services securely, using service tickets generated by the TGS.</td></tr><tr><td><code>389/TCP</code></td><td>LDAP</td><td><strong>Lightweight Directory Access Protocol</strong> - Vendor-neutral protocol designed for accessing and managing directory information services. Common uses include user authentication on internal resources, address books, or device management. Each entry in the LDAP directory has a Distinguished Name (DN), and attributes (key-value pairs) depending on the type of the entry (a user, a printer, a group...).</td></tr><tr><td><code>443/TCP</code></td><td>HTTPS</td><td><strong>HyperText Transfer Protocol Secure</strong> - Extension of HTTP that uses encryption (SSL/TLS) to secure the transmitted data. HTTPS provides confidentiality, data integrity, and authentication by encrypting the communication between the client and server using protocols like TLS 1.2 or TLS 1.3.</td></tr><tr><td><code>445/TCP</code></td><td>SMB</td><td><strong>Server Message Block</strong> - Network file sharing protocol that allows applications to read and write to files and request services from server programs in a computer network. SMB operates over TCP/IP and is used for sharing files, printers, and other resources. Recent versions provide authentication, authorization, and encryption (&gt; SMB 3.0), but badly configured SMB shares can be good entry points inside an information system (see <a href="https://learn.microsoft.com/fr-fr/security-updates/securitybulletins/2017/ms17-010" target="_blank" rel="noreferrer">EternalBlue MS17-010</a>).</td></tr><tr><td><code>554/TCP</code></td><td>RTSP</td><td><strong>Real-Time Streaming Protocol</strong> - Control protocol for streaming media, allowing clients to remotely control media servers with commands like PLAY, PAUSE, and TEARDOWN. RTSP typically works with RTP (Real-time Transport Protocol) for media delivery and supports both unicast and multicast streaming. It is widely used in video conferencing services (like MS Teams), surveillance, and entertainment systems.</td></tr><tr><td><code>1433/TCP</code></td><td>MSSQL</td><td>Default port for <strong>Microsoft SQL Server</strong> - MSSQL employs the Tabular Data Stream (TDS) protocol for client-server interactions, enabling standard data management operations (CRUD).</td></tr><tr><td><code>2049/TCP</code></td><td>NFS</td><td><strong>Network File System</strong> - Distributed file system protocol that allows clients to access files on remote servers as if they were local. NFS supports standard file operations like reading, writing, and locking, and recent versions have improved security, including Kerberos authentication and ACLs. It is commonly used in UNIX/Linux environments for shared storage and data access across networks.</td></tr><tr><td><code>3306/TCP</code></td><td>MySQL</td><td>Default port used by the <strong>MySQL DBMS</strong> for client-server communication. MySQL uses a proprietary protocol for communication between the client and server, allowing clients to connect to the database server and perform standard data operations like querying, updating, and managing data.</td></tr><tr><td><code>3389/TCP</code></td><td>RDP</td><td><strong>Remote Desktop Protocol</strong> - Proprietary Microsoft protocol that allows remote connection to a computer over a network. RDP provides graphical interface display, and input capabilities, so that users can interact with the computer as if they had physical access.</td></tr><tr><td><code>5985/TCP</code> or <code>5986/TCP</code></td><td>WinRM</td><td><strong>Windows Remote Management</strong> - Protocol that allows administrators to manage and configure Windows machines remotely. WinRM is Microsoft&#39;s implementation of the WS-Management protocol, which uses SOAP (Simple Object Access Protocol) over HTTP/HTTPS to provide a common way for systems to access and exchange management information. Tools like <a href="https://github.com/Hackplayers/evil-winrm" target="_blank" rel="noreferrer">EvilWinRM</a> can help exploit bad WinRM configurations.</td></tr></tbody></table>',8)]))}const u=t(n,[["render",s]]);export{h as __pageData,u as default};
